async function transfer(fromId, toId, amount) {
  // debit the sender on its shard
  const ok = await shardOf(fromId).debit(fromId, amount);  // false if insufficient
  if (!ok) return { status: 'declined' };

  // credit the receiver on its shard
  await shardOf(toId).credit(toId, amount);

  return { status: 'done' };
}
